import { GoogleGenerativeAI } from '@google/generative-ai';
import { ENV } from '../config/env';
import { prisma } from '../config/prisma';
import { retrievalService } from './retrieval.service';

export interface GeneratedSummary {
  quickOverview: string;
  mainIdeas: string[];
  keyTakeaways: string[];
  importantConcepts: { title: string; explanation: string }[];
}

export interface BookSummaryResult extends GeneratedSummary {
  /** 'ai' = generated by the AI provider; 'extractive-fallback' = sentences taken from the book text. */
  source: 'ai' | 'extractive-fallback';
  model?: string;
  fallbackReason?: string;
  cached?: boolean;
}

export const SUMMARY_CHUNK_CHARS = 12000;
export const SUMMARY_MAX_CHUNKS = 12;

/**
 * Split ordered book sections into bounded text chunks. If the book needs more
 * than `maxChunks`, chunks are sampled evenly across the whole book so the
 * summary still covers beginning, middle and end.
 */
export function chunkSectionsForSummary(
  sections: { title: string; text: string }[],
  chunkChars: number,
  maxChunks: number
): string[] {
  const chunks: string[] = [];
  let buf = '';
  for (const s of sections) {
    let rest = `${s.title}: ${s.text}`;
    while (rest.length > 0) {
      const room = chunkChars - buf.length;
      buf += rest.slice(0, room) + ' ';
      rest = rest.slice(room);
      if (buf.length >= chunkChars) { chunks.push(buf.trim()); buf = ''; }
    }
  }
  if (buf.trim()) chunks.push(buf.trim());
  if (chunks.length <= maxChunks) return chunks;
  const step = chunks.length / maxChunks;
  return Array.from({ length: maxChunks }, (_, i) => chunks[Math.floor(i * step)]);
}

export interface GeneratedFlashcard {
  question: string;
  answer: string;
}

export interface GeneratedQuiz {
  question: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
}

export interface MindMapNode {
  title: string;
  children: MindMapNode[];
}

export class AIService {
  private genAI: GoogleGenerativeAI | null = null;
  // gemini-1.5-flash is retired (404). Configurable so the model can follow Google's
  // deprecation schedule without a code change: https://ai.google.dev/gemini-api/docs/deprecations
  private modelName = ENV.GEMINI_MODEL;

  constructor() {
    if (ENV.GEMINI_API_KEY && ENV.GEMINI_API_KEY !== 'YOUR_GEMINI_API_KEY') {
      try {
        this.genAI = new GoogleGenerativeAI(ENV.GEMINI_API_KEY);
      } catch (err) {
        console.warn('Failed to initialize Gemini AI Client with provided key:', err);
      }
    }
  }

  private isGeminiConfigured(): boolean {
    return Boolean(
      this.genAI && ENV.GEMINI_API_KEY && ENV.GEMINI_API_KEY !== 'YOUR_GEMINI_API_KEY'
    );
  }

  private cleanJsonResponse(rawText: string): string {
    let cleaned = rawText.trim();
    if (cleaned.startsWith('```json')) {
      cleaned = cleaned.replace(/^```json\s*/i, '').replace(/\s*```$/, '');
    } else if (cleaned.startsWith('```')) {
      cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
    }
    return cleaned.trim();
  }

  /**
   * Summarize Book (with database caching)
   */
  /**
   * Full-book summary (with database caching).
   *
   * - Uses the text of EVERY chapter (not just the first few), in order.
   * - Long books are split into bounded chunks; with Gemini each chunk is
   *   summarized and the partial summaries are combined (map-reduce).
   * - Without a working AI provider an explicitly labelled extractive summary
   *   built from the same text is returned (`source: 'extractive-fallback'`).
   * - A book with no extractable text throws a typed 422 error instead of
   *   being "summarized" from its title or description.
   * - Cached entries without a `source` tag were produced by the old
   *   placeholder logic and are ignored (regenerated).
   */
  async summarizeBook(bookId: string, userId?: string, forceRefresh = false): Promise<BookSummaryResult> {
    if (!forceRefresh) {
      const cached = await prisma.summary.findFirst({
        where: { bookId, summaryType: 'book' },
        orderBy: { updatedAt: 'desc' }
      });
      if (cached?.content) {
        try {
          const parsed = JSON.parse(cached.content);
          if (parsed && (parsed.source === 'ai' || parsed.source === 'extractive-fallback')) {
            return { ...parsed, cached: true };
          }
        } catch {
          // Unparseable legacy cache: regenerate below.
        }
      }
    }

    const book = await prisma.book.findUnique({
      where: { id: bookId },
      include: {
        chapters: {
          orderBy: { chapterNumber: 'asc' },
          include: {
            contentBlocks: { select: { text: true }, orderBy: { blockIndex: 'asc' } }
          }
        }
      }
    });

    if (!book) {
      throw Object.assign(new Error('Book not found.'), { statusCode: 404, code: 'NOT_FOUND' });
    }
    if (book.processingStatus === 'PROCESSING') {
      throw Object.assign(new Error('This book is still being processed (OCR). Generate the summary when processing has finished.'), { statusCode: 409, code: 'BOOK_PROCESSING' });
    }

    const sections = book.chapters
      .map((c) => ({ title: c.title, text: c.contentBlocks.map((b) => b.text).join(' ').replace(/\s+/g, ' ').trim() }))
      .filter((s) => s.text.length > 0);
    const totalChars = sections.reduce((n, s) => n + s.text.length, 0);

    console.log(`[AI REQUEST] Full-book summary for book [ID: ${bookId}]: ${sections.length} sections, ${totalChars} characters of extracted text`);

    if (totalChars < 40) {
      throw Object.assign(
        new Error(
          book.isScanned
            ? 'This PDF is a scanned document without a text layer. Run text recognition (OCR) on it first, then generate the summary.'
            : 'No readable text was extracted from this book, so a summary cannot be generated.'
        ),
        { statusCode: 422, code: book.isScanned ? 'NEEDS_OCR' : 'NO_EXTRACTABLE_TEXT' }
      );
    }

    let summaryResult: BookSummaryResult;

    if (this.isGeminiConfigured() && this.genAI) {
      try {
        summaryResult = { ...(await this.summarizeWithGemini(book.title, book.author, sections)), source: 'ai', model: this.modelName };
        console.log(`[AI RESPONSE] Gemini (${this.modelName}) returned a full-book summary.`);
      } catch (err: any) {
        // Never surface provider internals or keys; log the class of failure only.
        const detail = err?.status ? `HTTP ${err.status}` : err?.name || 'request failed';
        console.warn(`[AI] Gemini summary failed (${detail}); using labelled extractive fallback.`);
        summaryResult = {
          ...this.createFallbackBookSummary(book),
          fallbackReason: `The AI provider request failed (${detail}), so this summary was extracted directly from the book text.`
        };
      }
    } else {
      summaryResult = {
        ...this.createFallbackBookSummary(book),
        fallbackReason: 'No AI provider is configured (GEMINI_API_KEY is missing or a placeholder), so this summary was extracted directly from the book text.'
      };
    }

    await prisma.summary.create({
      data: {
        userId: userId || null,
        bookId,
        summaryType: 'book',
        content: JSON.stringify(summaryResult)
      }
    });

    return summaryResult;
  }

  /** Map-reduce summary over bounded chunks so long books never exceed one request. */
  private async summarizeWithGemini(
    title: string,
    author: string,
    sections: { title: string; text: string }[]
  ): Promise<GeneratedSummary> {
    const model = this.genAI!.getGenerativeModel({ model: this.modelName });
    const chunks = chunkSectionsForSummary(sections, SUMMARY_CHUNK_CHARS, SUMMARY_MAX_CHUNKS);
    console.log(`[CHUNKING] ${chunks.length} chunk(s) of up to ${SUMMARY_CHUNK_CHARS} chars for model ${this.modelName}`);

    const partials: string[] = [];
    for (let i = 0; i < chunks.length; i++) {
      const res = await model.generateContent(
        `Summarize part ${i + 1} of ${chunks.length} of the book "${title}" by ${author}. ` +
          `Use only the text below. Write 4-6 sentences in the same language as the text.\n\n${chunks[i]}`
      );
      partials.push(res.response.text().trim());
    }

    const combined = await model.generateContent(`You are the AI literary companion for the reading app Elunè.
Combine these partial summaries of the book "${title}" by ${author} into ONE coherent full-book summary.
Use only information from the partial summaries. Write in the same language as the partial summaries.
Return ONLY valid JSON matching exactly:
{
  "quickOverview": "3-5 sentence overview of the whole book",
  "mainIdeas": ["...", "...", "..."],
  "keyTakeaways": ["...", "...", "..."],
  "importantConcepts": [{"title": "...", "explanation": "..."}]
}

Partial summaries:
${partials.map((p, i) => `[Part ${i + 1}] ${p}`).join('\n\n')}`);
    return JSON.parse(this.cleanJsonResponse(combined.response.text()));
  }

  /**
   * Summarize Chapter (with database caching)
   */
  async summarizeChapter(chapterId: string, userId?: string, forceRefresh = false): Promise<{ summary: string; keyPoints: string[] }> {
    if (!forceRefresh) {
      const cached = await prisma.summary.findFirst({
        where: { chapterId, summaryType: 'chapter' }
      });
      if (cached) {
        try {
          return JSON.parse(cached.content);
        } catch {
          return { summary: cached.content, keyPoints: [] };
        }
      }
    }

    const chapter = await prisma.chapter.findUnique({
      where: { id: chapterId },
      include: {
        book: true,
        contentBlocks: { select: { text: true }, orderBy: { blockIndex: 'asc' } }
      }
    });

    if (!chapter) {
      throw new Error(`Chapter with id ${chapterId} not found`);
    }

    const chapterText = chapter.contentBlocks.map((b) => b.text).join('\n\n');
    if (!chapterText || chapterText.trim().length === 0 || chapterText.includes('could not be converted into readable text')) {
      throw new Error('This chapter does not contain readable text for summarization.');
    }

    let result: { summary: string; keyPoints: string[] };

    if (this.isGeminiConfigured() && this.genAI) {
      try {
        const model = this.genAI.getGenerativeModel({ model: this.modelName });
        const prompt = `Summarize Chapter ${chapter.chapterNumber} ("${chapter.title}") from the book "${chapter.book.title}" by ${chapter.book.author}.
Return ONLY valid JSON matching this exact structure:
{
  "summary": "Concise summary of the chapter content",
  "keyPoints": ["Point 1", "Point 2", "Point 3"]
}

Chapter Content:
${chapterText.slice(0, 5000)}`;

        const genRes = await model.generateContent(prompt);
        const jsonStr = this.cleanJsonResponse(genRes.response.text());
        result = JSON.parse(jsonStr);
      } catch (err) {
        console.warn('Gemini chapter summary failed, using content fallback:', err);
        result = extractiveChapterSummary(chapter.contentBlocks.map((b) => b.text));
      }
    } else {
      result = extractiveChapterSummary(chapter.contentBlocks.map((b) => b.text));
    }

    // Cache to DB
    await prisma.summary.create({
      data: {
        userId: userId || null,
        bookId: chapter.bookId,
        chapterId: chapter.id,
        summaryType: 'chapter',
        content: JSON.stringify(result)
      }
    });

    return result;
  }

  /**
   * AI Book Q&A with strict context prompt
   */
  /**
   * Book Q&A. Only a real AI answer counts as an answer: if the provider is not
   * configured or fails, a typed error is thrown (no passage dressed up as an
   * answer). The context comes only from this book's extracted/OCR text, with
   * page references so the model can cite them.
   */
  async askBookQuestion(bookId: string, question: string, userId: string): Promise<string> {
    const book = await prisma.book.findUnique({ where: { id: bookId } });
    if (!book) {
      throw Object.assign(new Error('Book not found.'), { statusCode: 404, code: 'NOT_FOUND' });
    }
    if (book.processingStatus === 'PROCESSING') {
      throw Object.assign(new Error('This book is still being processed (OCR). Ask again when processing has finished.'), { statusCode: 409, code: 'BOOK_PROCESSING' });
    }

    const passages = await retrievalService.retrievePagePassages(bookId, question);
    if (passages.length === 0) {
      throw Object.assign(
        new Error(
          book.isScanned
            ? 'This scanned PDF has no recognized text yet. Run OCR on it first, then ask again.'
            : 'No readable text was extracted from this book, so questions cannot be answered.'
        ),
        { statusCode: 422, code: book.isScanned ? 'NEEDS_OCR' : 'NO_EXTRACTABLE_TEXT' }
      );
    }

    if (!this.isGeminiConfigured() || !this.genAI) {
      throw Object.assign(
        new Error('AI is not configured on the server. Set GEMINI_API_KEY in backend/.env and restart the backend.'),
        { statusCode: 503, code: 'AI_NOT_CONFIGURED' }
      );
    }

    const context = passages.map((p) => `[Page ${p.pageNumber}] ${p.text}`).join('\n\n');
    let answer = '';
    try {
      const model = this.genAI.getGenerativeModel({ model: this.modelName });
      const genRes = await model.generateContent(`You are the reading companion for the book "${book.title}" by ${book.author} in the Elunè app.
Answer the question using ONLY the book passages below. Cite the page numbers you used, like (p. 12).
If the passages do not contain the answer, say clearly that the book passages provided do not answer it. Do not invent facts.
Answer in the language of the question.

Book passages:
${context}

Question: ${question}`);
      answer = genRes.response.text().trim();
    } catch (err: any) {
      // Sanitized: status / name only, never the request, key or full provider payload.
      const detail = err?.status ? `HTTP ${err.status}` : err?.name || 'request failed';
      console.warn(`[AI] Gemini Q&A failed (${detail}).`);
      throw Object.assign(new Error(`The AI provider could not answer (${detail}). Check the API key and model, then try again.`), {
        statusCode: 502,
        code: 'AI_PROVIDER_ERROR'
      });
    }
    if (!answer) {
      throw Object.assign(new Error('The AI provider returned an empty answer.'), { statusCode: 502, code: 'AI_PROVIDER_ERROR' });
    }

    await prisma.aIChat.create({
      data: {
        userId,
        bookId,
        question,
        answer
      }
    });

    return answer;
  }

  /**
   * Generate Flashcards
   */
  async generateFlashcards(bookId: string, userId?: string): Promise<GeneratedFlashcard[]> {
    const book = await prisma.book.findUnique({
      where: { id: bookId },
      include: {
        chapters: {
          include: {
            contentBlocks: { select: { text: true }, orderBy: { blockIndex: 'asc' } }
          },
          take: 3
        }
      }
    });

    if (!book) throw new Error(`Book ${bookId} not found`);

    let flashcards: GeneratedFlashcard[] = [];

    if (this.isGeminiConfigured() && this.genAI) {
      try {
        const model = this.genAI.getGenerativeModel({ model: this.modelName });
        const contextText = book.chapters
          .map((c) => `${c.title}: ${c.contentBlocks.map((b) => b.text).join(' ').slice(0, 1000)}`)
          .join('\n');
        const prompt = `Generate 5 high-yield study flashcards from the book "${book.title}" by ${book.author}.
Return ONLY valid JSON array with format:
[
  {
    "question": "Clear, thought-provoking question",
    "answer": "Concise, definitive answer based on the book"
  }
]

Book context:
${contextText}`;

        const genRes = await model.generateContent(prompt);
        flashcards = JSON.parse(this.cleanJsonResponse(genRes.response.text()));
      } catch (err) {
        console.warn('Gemini flashcard failed, using fallback:', err);
        flashcards = this.generateFallbackFlashcards(book);
      }
    } else {
      flashcards = this.generateFallbackFlashcards(book);
    }

    for (const fc of flashcards) {
      await prisma.flashcard.create({
        data: {
          userId: userId || null,
          bookId,
          question: fc.question,
          answer: fc.answer
        }
      });
    }

    return flashcards;
  }

  /**
   * Generate Quiz
   */
  async generateQuiz(bookId: string, userId?: string): Promise<GeneratedQuiz[]> {
    const book = await prisma.book.findUnique({
      where: { id: bookId },
      include: {
        chapters: {
          include: {
            contentBlocks: { select: { text: true }, orderBy: { blockIndex: 'asc' } }
          },
          take: 3
        }
      }
    });

    if (!book) throw new Error(`Book ${bookId} not found`);

    let quizzes: GeneratedQuiz[] = [];

    if (this.isGeminiConfigured() && this.genAI) {
      try {
        const model = this.genAI.getGenerativeModel({ model: this.modelName });
        const contextText = book.chapters
          .map((c) => `${c.title}: ${c.contentBlocks.map((b) => b.text).join(' ').slice(0, 1000)}`)
          .join('\n');
        const prompt = `Generate 4 multiple-choice quiz questions based strictly on the book "${book.title}" by ${book.author}.
Return ONLY valid JSON array with format:
[
  {
    "question": "Question text based on the text",
    "options": ["Option A", "Option B", "Option C", "Option D"],
    "correctAnswer": "Exact text of the correct option",
    "explanation": "Clear explanation citing the book principle"
  }
]

Context:
${contextText}`;

        const genRes = await model.generateContent(prompt);
        quizzes = JSON.parse(this.cleanJsonResponse(genRes.response.text()));
      } catch (err) {
        console.warn('Gemini quiz failed, using fallback:', err);
        quizzes = this.generateFallbackQuiz(book);
      }
    } else {
      quizzes = this.generateFallbackQuiz(book);
    }

    for (const q of quizzes) {
      await prisma.quiz.create({
        data: {
          userId: userId || null,
          bookId,
          question: q.question,
          options: JSON.stringify(q.options),
          correctAnswer: q.correctAnswer,
          explanation: q.explanation
        }
      });
    }

    return quizzes;
  }

  /**
   * Generate Mind Map (JSON hierarchical tree)
   */
  async generateMindMap(bookId: string): Promise<MindMapNode> {
    const book = await prisma.book.findUnique({
      where: { id: bookId },
      include: {
        chapters: {
          select: { title: true }
        }
      }
    });

    if (!book) throw new Error(`Book ${bookId} not found`);

    if (this.isGeminiConfigured() && this.genAI) {
      try {
        const model = this.genAI.getGenerativeModel({ model: this.modelName });
        const prompt = `Generate a hierarchical mind map structure for the book "${book.title}" by ${book.author}.
Return ONLY valid JSON matching this exact structure:
{
  "title": "${book.title}",
  "children": [
    {
      "title": "Main Theme 1",
      "children": [
        { "title": "Subtheme A", "children": [] },
        { "title": "Subtheme B", "children": [] }
      ]
    },
    {
      "title": "Main Theme 2",
      "children": [
        { "title": "Subtheme C", "children": [] }
      ]
    }
  ]
}`;

        const genRes = await model.generateContent(prompt);
        return JSON.parse(this.cleanJsonResponse(genRes.response.text()));
      } catch (err) {
        console.warn('Gemini mind map failed, using fallback:', err);
      }
    }

    return {
      title: book.title,
      children: book.chapters.map((ch) => ({
        title: ch.title,
        children: [
          { title: 'Core Principle', children: [] },
          { title: 'Actionable Reflection', children: [] }
        ]
      }))
    };
  }

  /**
   * Non-AI fallback (no Gemini key, or Gemini failed): an EXTRACTIVE summary
   * built only from this book's own text, so it never describes another book.
   */
  private createFallbackBookSummary(book: any): BookSummaryResult {
    const chapterTexts = ((book.chapters || []) as any[])
      .map((c) => ({
        title: c.title as string,
        text: (c.contentBlocks || []).map((b: any) => b.text).join(' ').replace(/\s+/g, ' ').trim()
      }))
      .filter((c) => c.text.length > 0);

    // Sample sentences evenly across the WHOLE book (beginning, middle, end).
    const allSentences = chapterTexts.flatMap((c) => splitSentences(c.text));
    const pick = (n: number) => {
      if (allSentences.length <= n) return allSentences;
      const step = allSentences.length / n;
      return Array.from({ length: n }, (_, i) => allSentences[Math.floor(i * step)]);
    };
    const overview = pick(4).map((s) => truncateWords(s, 45)).join(' ');
    const evenChapters = (() => {
      if (chapterTexts.length <= 5) return chapterTexts;
      const step = chapterTexts.length / 5;
      return Array.from({ length: 5 }, (_, i) => chapterTexts[Math.floor(i * step)]);
    })();

    return {
      source: 'extractive-fallback',
      quickOverview: overview,
      mainIdeas: evenChapters.map((c) => `${c.title}: ${firstSentences(c.text, 1)}`),
      keyTakeaways: pick(7).slice(4).map((s) => truncateWords(s, 40)),
      importantConcepts: evenChapters.slice(0, 3).map((c) => ({ title: c.title, explanation: truncateWords(c.text, 40) }))
    };
  }

  /** Non-AI fallback answer: quotes the retrieved passages of THIS book only. */
  private generateFallbackAnswer(book: any, _question: string, context: string): string {
    const passage = (context || '').replace(/\s+/g, ' ').trim();
    if (passage.length > 0) {
      return `AI is not configured, so this is the most relevant passage from "${book.title}" rather than a generated answer:\n\n"${truncateWords(passage, 80)}"`;
    }
    return `The answer could not be found in "${book.title}".`;
  }

  /** Non-AI fallback flashcards built from this book's own chapters (no invented content). */
  private generateFallbackFlashcards(book: any): GeneratedFlashcard[] {
    return (book.chapters || [])
      .map((c: any) => ({
        title: c.title as string,
        text: (c.contentBlocks || []).map((b: any) => b.text).join(' ')
      }))
      .filter((c: any) => c.text.trim().length > 0)
      .slice(0, 5)
      .map((c: any) => ({
        question: `What does "${c.title}" in "${book.title}" open with?`,
        answer: firstSentences(c.text, 2)
      }));
  }

  /**
   * Non-AI fallback quiz: "which chapter contains this passage?" using this
   * book's own chapter titles. Needs at least two chapters with text; otherwise
   * no quiz is produced rather than inventing questions.
   */
  private generateFallbackQuiz(book: any): GeneratedQuiz[] {
    const chapters = (book.chapters || [])
      .map((c: any) => ({
        title: c.title as string,
        text: (c.contentBlocks || []).map((b: any) => b.text).join(' ')
      }))
      .filter((c: any) => c.text.trim().length > 0);
    const titles: string[] = Array.from(new Set<string>(chapters.map((c: any) => c.title)));
    if (titles.length < 2) return [];
    return chapters.slice(0, 4).map((c: any, idx: number) => {
      const distractors = titles.filter((t) => t !== c.title).slice(0, 3);
      const options = [...distractors];
      options.splice(idx % (distractors.length + 1), 0, c.title);
      return {
        question: `Which section of "${book.title}" contains this passage: "${truncateWords(firstSentences(c.text, 1), 30)}"?`,
        options,
        correctAnswer: c.title,
        explanation: `The passage is taken from "${c.title}".`
      };
    });
  }
}

/** Non-AI chapter summary: the chapter's own opening sentences and paragraph leads. */
function extractiveChapterSummary(paragraphs: string[]): { summary: string; keyPoints: string[]; source: 'extractive-fallback' } {
  const nonEmpty = paragraphs.filter((p) => (p || '').trim().length > 0);
  return {
    source: 'extractive-fallback',
    summary: firstSentences(nonEmpty.join(' '), 3),
    keyPoints: nonEmpty.slice(1, 4).map((p) => firstSentences(p, 1))
  };
}

function splitSentences(text: string): string[] {
  const clean = (text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return [];
  return (clean.match(/[^.!?]+[.!?]+(\s|$)|[^.!?]+$/g) || [clean]).map((s) => s.trim()).filter((s) => s.length > 15);
}

/** First `n` sentences of a text (used by the extractive, non-AI fallbacks). */
function firstSentences(text: string, n: number): string {
  const clean = (text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return '';
  const sentences = clean.match(/[^.!?]+[.!?]+(\s|$)/g) || [clean];
  return truncateWords(sentences.slice(0, n).join(' ').trim(), 60);
}

function truncateWords(text: string, maxWords: number): string {
  const words = (text || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  return words.length > maxWords ? `${words.slice(0, maxWords).join(' ')}…` : words.join(' ');
}

export const aiService = new AIService();
